 UPDATE CMN_ATTC_FILE
    SET FILE_STAT_RCD = 'CMN101.SAVE'
 WHERE ATTC_FILE_NO = #{ATTC_FILE_NO}

mapper.insert:

INSERT INTO CMN_ATTC_FILE(
		
      ATTC_FILE_NO
     , SEQ
     , PGM_ID
     , USER_ID
     , FILE_NM
     , SAVE_FILE_NM
     , FILE_PATH
     , FILE_EXT
     , FILE_SIZE
     , FILE_STAT_RCD
     , CRT_DTHR 
     , CRT_USER_ID 
     , CRT_PGM_ID 
     , CRT_IP_MAC 
     , UPD_DTHR 
     , UPD_USER_ID 
     , UPD_PGM_ID 
     , UPD_IP_MAC 
	
	)
VALUES(
	
      #{ATTC_FILE_NO}
     , (SELECT IFNULL(MAX(SEQ),0)+1 FROM CMN_ATTC_FILE T WHERE ATTC_FILE_NO = #{ATTC_FILE_NO})
     , #{PGM_ID}
     , #{USER_ID}
     , #{FILE_NM}
     , #{SAVE_FILE_NM}
     , #{FILE_PATH}
     , #{FILE_EXT}
     , #{FILE_SIZE}
     , (SELECT CASE WHEN EXISTS (SELECT 1 FROM CMN_ATTC_FILE T WHERE ATTC_FILE_NO = #{ATTC_FILE_NO} AND FILE_STAT_RCD = 'CMN101.SAVE') 
     			THEN 'CMN101.SAVE'
     		ELSE #{FILE_STAT_RCD}
     	END FROM INFORMATION_SCHEMA.SYSTEM_USERS)
     , SYSDATE 
     , #{CRT_USER_ID} 
     , #{CRT_PGM_ID} 
     , #{CRT_IP_MAC} 
     , SYSDATE 
     , #{UPD_USER_ID} 
     , #{UPD_PGM_ID} 
     , #{UPD_IP_MAC} 
)

mapper.select:
SELECT ATTC_FILE_NO , SEQ , PGM_ID , USER_ID , FILE_NM , SAVE_FILE_NM , FILE_PATH , FILE_EXT , FILE_SIZE , CASE WHEN FILE_STAT_RCD = 'CMN101.SAVE' THEN '저장완료' ELSE '임시저장' END AS FILE_STAT_NM , CRT_DTHR , CASE WHEN LOWER(FILE_EXT) IN ('doc', 'docx') THEN 'theme/images/icon/file_icon_DOC.png' WHEN LOWER(FILE_EXT) IN ('xls', 'xlsx') THEN 'theme/images/icon/file_icon_XLS.png' WHEN LOWER(FILE_EXT) IN ('ppt', 'pptx') THEN 'theme/images/icon/file_icon_PPT.png' WHEN LOWER(FILE_EXT) IN ('pdf') THEN 'theme/images/icon/file_icon_PDF.png' WHEN LOWER(FILE_EXT) IN ('txt') THEN 'theme/images/icon/file_icon_TXT.png' WHEN LOWER(FILE_EXT) IN ('zip', 'egg') THEN 'theme/images/icon/file_icon_ZIP.png' WHEN LOWER(FILE_EXT) IN ('png', 'gif', 'jpg', 'jpeg', 'bmp', 'tif', 'tiff') THEN 'theme/images/icon/file_icon_IMG.png' ELSE 'theme/images/icon/file_icon_ETC.png' END AS FILE_ICON_IMG FROM CMN_ATTC_FILE WHERE ATTC_FILE_NO = #{ATTC_FILE_NO}
AND SEQ = #{SEQ}
AND FILE_STAT_RCD = #{FILE_STAT_RCD}
ORDER BY SEQ

mapper.delete:
		
DELETE 
  FROM CMN_ATTC_FILE
 WHERE ATTC_FILE_NO = #{ATTC_FILE_NO__origin}
  AND SEQ = #{SEQ__origin}

mapper.select:
		/* QueryId : cmn-base01.selectCmnCodeList */
        
        SELECT 
               CD                       /*코드*/ 
             , UCD                      /*상위코드*/ 
             , CD_CLS                   /*코드분류*/ 
             , CD_NM || CASE WHEN USE_YN = 'Y' THEN '' ELSE '【폐지】' END AS CD_NM /*코드명*/ 
             , CD_SHORT_NM              /*코드약칭*/ 
          FROM CMN_CODE 
         WHERE CD_CLS = #{CD_CLS}
        
          
          AND CD = #{CD} 
          
          
          AND UCD = #{UCD} 
          
          
          AND SYSDATE BETWEEN EFFT_STAT_DT AND EFFT_END_DT 
                       
          
          AND USE_YN = #{USE_YN} 
               
          
          AND (   CD_NM LIKE  '%'||#{CD_NM}||'%' 
               OR CD  LIKE '%'||#{CD_NM}||'%'
               OR ENG_NM  LIKE '%'||#{CD_NM}||'%'                    
              )
           
          
          AND UNIT_SYSTEM_RCD = #{UNIT_SYSTEM_RCD} 
           
          
          AND CD = #{CD} 
                   
          
          AND CD_PRP1 = #{CD_PRP1} 
           
          
          AND CD_PRP2 = #{CD_PRP2} 
           
          
          AND CD_PRP3 = #{CD_PRP3} 
           
          
          AND CD_PRP4 = #{CD_PRP4} 
           
          
          AND CD_PRP5 = #{CD_PRP5} 
           
          
          AND CD_PRP6 = #{CD_PRP6} 
           
          
          AND CD_PRP7 = #{CD_PRP7} 
           
          
          AND CD_PRP8 = #{CD_PRP8} 
           
          
          AND CD_PRP9 = #{CD_PRP9} 
           
          
          AND CD_PRP10 = #{CD_PRP10} 
           
          
          AND CD_PRP11 = #{CD_PRP11} 
           
          
          AND CD_PRP12 = #{CD_PRP12} 
           
          
          AND CD_PRP13 = #{CD_PRP13} 
           
          
          AND CD_PRP14 = #{CD_PRP14} 
           
          
          AND CD_PRP15 = #{CD_PRP15} 
           
          
          AND CD_PRP16 = #{CD_PRP16} 
                     
          
          AND CD_PRP17 = #{CD_PRP17} 
                     
          
          AND CD_PRP18 = #{CD_PRP18} 
                     
          
          AND CD_PRP19 = #{CD_PRP19} 
                     
          
          AND CD_PRP20 = #{CD_PRP20} 
                               
          
          ORDER BY  ${ORDER_BY}
